svg.script:
(() => {
  const ns = 'http://www.w3.org/2000/svg'
  const cx = 300, cy = 300, radius = 184
  const colors = { A: '#2563eb', B: '#db552f', C: '#20966f', D: '#7c3aed' }
  const initial = [
    { angle: -80, owner: 'A' }, { angle: -35, owner: 'B' },
    { angle: 5, owner: 'C' }, { angle: 20, owner: 'A' },
    { angle: 75, owner: 'B' }, { angle: 110, owner: 'C' },
    { angle: 140, owner: 'A' }, { angle: 195, owner: 'B' },
    { angle: 240, owner: 'C' }
  ]
  const joining = [
    { angle: -55, owner: 'D' }, { angle: 52, owner: 'D' },
    { angle: 165, owner: 'D' }
  ]

  const svg = document.querySelector('#dynamo-strategy-1')
  const ranges = document.querySelector('#ranges')
  const transfers = document.querySelector('#transfers')
  const tokens = document.querySelector('#tokens')
  const autoplayControl = document.querySelector('#autoplay-control')
  const text = id => document.querySelector('#' + id)
  const states = ['initial', 'join', 'move']
  let currentState = 'initial'
  let playing = !window.matchMedia('(prefers-reduced-motion: reduce)').matches
  let hoverPaused = false
  let focusPaused = false
  const point = (angle, r = radius) => {
    const radians = angle * Math.PI / 180
    return { x: cx + r * Math.cos(radians), y: cy + r * Math.sin(radians) }
  }
  const arc = (start, end) => {
    while (end <= start) end += 360
    const a = point(start), b = point(end)
    return `M ${a.x} ${a.y} A ${radius} ${radius} 0 ${end - start > 180 ? 1 : 0} 1 ${b.x} ${b.y}`
  }
  const sorted = values => [...values].sort((a, b) => a.angle - b.angle)
  const clear = element => { while (element.firstChild) element.removeChild(element.firstChild) }
  const element = (name, attributes) => {
    const result = document.createElementNS(ns, name)
    for (const [key, value] of Object.entries(attributes)) result.setAttribute(key, value)
    return result
  }

  function drawRing(values, changedOwners = false) {
    clear(ranges)
    clear(transfers)
    clear(tokens)
    const ordered = sorted(values)
    ordered.forEach((token, index) => {
      const previous = ordered[(index - 1 + ordered.length) % ordered.length]
      let start = previous.angle
      let end = token.angle
      if (index === 0) start -= 360
      const path = element('path', {
        d: arc(start, end),
        class: `range ${changedOwners && token.owner === 'D' ? 'changed' : ''}`,
        stroke: colors[token.owner]
      })
      ranges.appendChild(path)
      if (changedOwners && token.owner === 'D') {
        const dot = element('circle', { class: 'transfer-dot', r: 6 })
        const motion = element('animateMotion', {
          dur: `${1.8 + index * 0.08}s`, begin: `${index * 0.12}s`,
          repeatCount: 'indefinite', path: path.getAttribute('d')
        })
        dot.appendChild(motion)
        transfers.appendChild(dot)
      }
    })
    ordered.forEach(token => {
      const p = point(token.angle)
      tokens.appendChild(element('circle', {
        class: 'token', cx: p.x, cy: p.y, r: 13, fill: colors[token.owner]
      }))
      const label = element('text', {
        class: 'token-label', x: p.x, y: p.y + 1, fill: '#ffffff'
      })
      label.textContent = token.owner
      tokens.appendChild(label)
    })
  }

  function showTargets() {
    joining.forEach(token => {
      const p = point(token.angle)
      const target = element('circle', {
        class: 'token target direct-control', cx: p.x, cy: p.y, r: 13,
        role: 'button', tabindex: '0', 'aria-label': 'Transfer this range to node D'
      })
      target.addEventListener('click', () => setState('move'))
      target.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          setState('move')
        }
      })
      tokens.appendChild(target)
      const label = element('text', {
        class: 'token-label', x: p.x, y: p.y + 1, fill: colors.D
      })
      label.textContent = 'D'
      tokens.appendChild(label)
    })
  }

  const copy = {
    initial: {
      title: '1. Initial placement', center: 'Initial ring', center1: 'A, B and C have random tokens', center2: 'Partitions have unequal sizes',
      lines: ['Every physical node receives several', 'random positions on the hash ring.', 'Adjacent tokens define the partitions,', 'so partitioning and placement are tied.'],
      costs: ['Observation:', 'Random token spacing creates ranges', 'with different sizes.']
    },
    join: {
      title: '2. Node D joins', center: 'D chooses tokens', center1: 'New positions are scattered', center2: 'around the ring',
      lines: ['D is assigned multiple random tokens.', 'The outlined tokens show its targets.', 'Because they are scattered, D needs data', 'from several existing physical nodes.'],
      costs: ['Consequence:', 'One joining node affects several', 'disjoint key ranges.']
    },
    move: {
      title: '3. Ranges move to D', center: 'Ranges reassigned', center1: 'Purple arcs now belong to D', center2: 'Each source scans and transfers data',
      lines: ['Each purple range previously belonged', 'to the next old token clockwise.', 'Those nodes scan local storage and send', 'the matching data to node D.'],
      costs: ['Operational cost:', 'I/O-heavy scans, slow bootstrapping,', 'and Merkle-tree recalculation.']
    }
  }

  function setCopy(state) {
    const value = copy[state]
    text('step-title').textContent = value.title
    text('center-title').textContent = value.center
    text('center-line-1').textContent = value.center1
    text('center-line-2').textContent = value.center2
    value.lines.forEach((line, i) => text(`line-${i + 1}`).textContent = line)
    value.costs.forEach((line, i) => text(`cost-${i + 1}`).textContent = line)
    ;['initial', 'join', 'move'].forEach(name => {
      document.querySelector(`#button-${name}`).classList.toggle('active', name === state)
    })
  }

  function setState(state) {
    currentState = state
    if (state === 'initial') drawRing(initial)
    if (state === 'join') { drawRing(initial); showTargets() }
    if (state === 'move') drawRing([...initial, ...joining], true)
    setCopy(state)
  }

  function updateAutoplayLabel() {
    text('autoplay-label').textContent = `AUTOPLAY: ${playing ? 'ON' : 'OFF'}`
    autoplayControl.setAttribute('aria-label', playing ? 'Pause automatic animation' : 'Start automatic animation')
  }

  function toggleAutoplay() {
    playing = !playing
    updateAutoplayLabel()
  }

  ;['initial', 'join', 'move'].forEach(state => {
    const button = document.querySelector(`#button-${state}`)
    button.addEventListener('click', () => setState(state))
    button.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault()
        setState(state)
      }
    })
  })

  const nodeD = document.querySelector('#node-d-control')
  nodeD.addEventListener('click', () => setState('join'))
  nodeD.addEventListener('keydown', event => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      setState('join')
    }
  })
  autoplayControl.addEventListener('click', toggleAutoplay)
  autoplayControl.addEventListener('keydown', event => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      toggleAutoplay()
    }
  })
  svg.addEventListener('mouseenter', () => { hoverPaused = true })
  svg.addEventListener('mouseleave', () => { hoverPaused = false })
  svg.addEventListener('focusin', () => { focusPaused = true })
  svg.addEventListener('focusout', () => { focusPaused = false })
  window.setInterval(() => {
    if (!playing || hoverPaused || focusPaused || document.hidden) return
    const next = (states.indexOf(currentState) + 1) % states.length
    setState(states[next])
  }, 3200)

  setState('initial')
  updateAutoplayLabel()
})()
